new = '''    def read_key(self) -> Optional[str]:
        if not self._keybuf:
            r, _, _ = select.select([sys.stdin], [], [], 0.2)
            if not r:
                return None
            data = os.read(sys.stdin.fileno(), 64)
            if not data:
                return None
            self._keybuf += data
        if not self._keybuf:
            return None
        # Recognize common escape sequences first.
        mapping = {
            b"\x1b[A": "UP", b"\x1b[B": "DOWN", b"\x1b[C": "RIGHT", b"\x1b[D": "LEFT",
            b"\x1b[H": "HOME", b"\x1b[F": "END", b"\x1b[3~": "DELETE",
            b"\x1b[5~": "PAGEUP", b"\x1b[6~": "PAGEDOWN", b"\x1b[15~": "F5",
        }
        if self._keybuf.startswith(b"\x1b"):
            for seq, name in sorted(mapping.items(), key=lambda kv: -len(kv[0])):
                if self._keybuf.startswith(seq):
                    self._keybuf = self._keybuf[len(seq):]
                    return name
            # In cbreak mode a lone escape is delivered immediately by tmux/script.
            self._keybuf = self._keybuf[1:]
            return "ESC"
        b0 = self._keybuf[:1]
        self._keybuf = self._keybuf[1:]
        if b0 == b"\x03":
            return "CTRL_C"
        if b0 in (b"\r", b"\n"):
            return "ENTER"
        if b0 in (b"\x7f", b"\b"):
            return "\x7f"
        try:
            return b0.decode("utf-8", "ignore")
        except UnicodeError:
            return None
'''
