from pathlib import Path
p=Path('src/igrep.py')
s=p.read_text()
old = '''def iter_files(paths: Sequence[str], args: Args) -> Iterable[Tuple[str, str]]:
    cwd = os.getcwd()
    for raw in paths:
        raw = raw or "."
        absroot = os.path.abspath(raw)
        raw_is_abs = os.path.isabs(raw)
        if os.path.isfile(raw) or (os.path.islink(raw) and not os.path.isdir(raw)):
            if not args.hidden and is_hidden_path(os.path.basename(raw)) and not os.path.exists(raw):
                continue
            disp = os.path.abspath(raw) if raw_is_abs else os.path.normpath(raw)
            if disp == ".":
                disp = os.path.basename(os.path.abspath(raw))
            yield raw, disp
            continue
        if not os.path.isdir(raw):
            continue
        for dirpath, dirnames, filenames in os.walk(raw, followlinks=args.follow):
            if not args.hidden:
                dirnames[:] = [d for d in dirnames if not d.startswith(".")]
                filenames = [f for f in filenames if not f.startswith(".")]
            for fname in filenames:
                fpath = os.path.join(dirpath, fname)
                if os.path.isdir(fpath):
                    continue
                if raw_is_abs:
                    disp = os.path.abspath(fpath)
                else:
                    disp = os.path.normpath(fpath)
                    if disp.startswith("." + os.sep):
                        disp = disp[2:]
                yield fpath, disp
'''
new = '''def iter_files(paths: Sequence[str], args: Args) -> Iterable[Tuple[str, str]]:
    def display_for(path: str, raw_is_abs: bool) -> str:
        if raw_is_abs:
            return os.path.abspath(path)
        disp = os.path.normpath(path)
        if disp.startswith("." + os.sep):
            disp = disp[2:]
        return disp

    def walk_dir(dirpath: str, raw_is_abs: bool, seen: set) -> Iterable[Tuple[str, str]]:
        try:
            entries = list(os.scandir(dirpath))
        except OSError:
            return
        file_entries = []
        dir_entries = []
        for ent in entries:
            name = ent.name
            if not args.hidden and name.startswith("."):
                continue
            try:
                is_dir = ent.is_dir(follow_symlinks=args.follow)
            except OSError:
                continue
            if is_dir:
                if ent.is_symlink() and not args.follow:
                    continue
                dir_entries.append(ent)
            else:
                file_entries.append(ent)
        # Observed result order is closest to ripgrep's parallel walker when
        # regular files in a directory are yielded in reverse entry order, then
        # subdirectories are visited in reverse entry order.
        for ent in reversed(file_entries):
            yield ent.path, display_for(ent.path, raw_is_abs)
        for ent in reversed(dir_entries):
            if args.follow:
                try:
                    real = os.path.realpath(ent.path)
                    if real in seen:
                        continue
                    seen.add(real)
                except OSError:
                    pass
            yield from walk_dir(ent.path, raw_is_abs, seen)

    for raw in paths:
        raw = raw or "."
        raw_is_abs = os.path.isabs(raw)
        if os.path.isfile(raw) or (os.path.islink(raw) and not os.path.isdir(raw)):
            yield raw, display_for(raw, raw_is_abs)
            continue
        if not os.path.isdir(raw):
            continue
        seen = {os.path.realpath(raw)} if args.follow else set()
        yield from walk_dir(raw, raw_is_abs, seen)
'''
if old not in s:
    raise SystemExit('old iter_files not found')
s=s.replace(old,new)
p.write_text(s)
